insert into public.concepts(id,course_id,slug,title,summary,order_index,content) values
('20000000-0000-4000-8000-000000000201','10000000-0000-4000-8000-000000000003','human-eye','The human eye','Parts of the eye and how a focused image forms on the retina.',0,$c${"explanation":"Light enters the eye through the transparent cornea, passes through the aqueous humour and the pupil, and is focused mainly by the crystalline lens onto the retina. The iris controls pupil size and therefore the amount of light admitted. The retina contains rod cells, sensitive to dim light, and cone cells, which detect colour. The image on the retina is real and inverted; the brain interprets it as upright. The optic nerve carries signals to the brain. The eye is a natural optical instrument whose lens system has a variable focal length.","examples":[{"problem":"Why does the pupil enlarge in a dark room?","solution":"The iris relaxes so the pupil widens, admitting more light to the retina for dim-light vision."},{"problem":"Is the image on the retina real or virtual, and upright or inverted?","solution":"It is real and inverted; the lens converges light onto the retina, and the brain interprets the signal."}],"misconceptions":["The image on the retina is upright.","The cornea plays no role in focusing light.","Rods detect colour while cones work in dim light."],"revision_notes":"Cornea and lens focus light, iris controls the pupil, retina detects light, optic nerve carries signals. Retinal image: real, inverted."}$c$::jsonb),
('20000000-0000-4000-8000-000000000202','10000000-0000-4000-8000-000000000003','accommodation','Accommodation','How the eye changes its focal length for near and distant objects.',1,$c${"explanation":"The eye focuses objects at different distances by changing the curvature of its lens, a process called accommodation. Ciliary muscles contract to make the lens thicker and shorter in focal length for nearby objects, and relax to flatten it for distant objects. For a normal eye the far point is infinity and the near point is about 25 cm for a young adult. The least distance of distinct vision is about 25 cm; closer objects appear blurred because the lens cannot become thick enough. The range of accommodation decreases with age.","examples":[{"problem":"What happens to the ciliary muscles when you read a book?","solution":"They contract, thickening the lens and reducing its focal length so nearby text focuses on the retina."},{"problem":"Why can a normal eye not focus clearly on an object 5 cm away?","solution":"That is inside the near point; the lens cannot bend enough to bring the rays to a focus on the retina."}],"misconceptions":["The eye moves its retina to focus.","The lens becomes thinner for near objects.","The near point is the same at every age."],"revision_notes":"Accommodation: ciliary muscles change lens curvature. Near point ≈ 25 cm; far point at infinity for a normal eye."}$c$::jsonb),
('20000000-0000-4000-8000-000000000203','10000000-0000-4000-8000-000000000003','vision-defects','Defects of vision','Myopia, hypermetropia and presbyopia, and their lens corrections.',2,$c${"explanation":"In myopia, or short-sightedness, the image of a distant object forms in front of the retina, so far objects are blurred; a concave lens of suitable power diverges the rays before they enter the eye. In hypermetropia, or long-sightedness, the image of a near object would form behind the retina, and a convex lens converges the rays to correct it. Presbyopia is the age-related loss of accommodation caused by stiffening of the lens; it is corrected with reading glasses. Astigmatism, caused by an unevenly curved cornea or lens, is corrected with a cylindrical lens.","examples":[{"problem":"A short-sighted student cannot read the board clearly. Which lens corrects this?","solution":"A concave (diverging) lens, which moves the image of a distant object back onto the retina."},{"problem":"An older person can see distant objects but needs glasses for reading. Name the defect.","solution":"Presbyopia: reduced accommodation makes near vision difficult, corrected with convex reading lenses."}],"misconceptions":["Myopia is corrected with a convex lens.","Hypermetropia means the eye is too long.","Presbyopia is the same as hypermetropia caused by a short eyeball."],"revision_notes":"Myopia: image in front of retina, concave lens. Hypermetropia: image behind retina, convex lens. Presbyopia: loss of accommodation with age."}$c$::jsonb),
('20000000-0000-4000-8000-000000000204','10000000-0000-4000-8000-000000000003','dispersion','Dispersion of light','Splitting white light into colours with a prism.',3,$c${"explanation":"White light is a mixture of colours. When it passes through a glass prism, different colours refract by different amounts because the refractive index of glass depends on wavelength. Violet light slows and bends the most, and red the least, so the emerging colours spread into a spectrum: red, orange, yellow, green, blue, indigo and violet. This separation is dispersion. A second, inverted prism can recombine the colours into white light. Rainbows form when sunlight is refracted, internally reflected and dispersed by water droplets.","examples":[{"problem":"Which colour deviates most when white light passes through a glass prism?","solution":"Violet, because glass has the highest refractive index for the shortest visible wavelength."},{"problem":"How can a spectrum be recombined into white light?","solution":"Pass it through a second prism arranged to bend the colours back together."}],"misconceptions":["The prism adds colour to white light.","Red bends more than violet in glass.","Dispersion happens because colours travel at the same speed in glass."],"revision_notes":"Dispersion: n depends on wavelength. Violet bends most, red least. Prisms can split or recombine white light."}$c$::jsonb),
('20000000-0000-4000-8000-000000000205','10000000-0000-4000-8000-000000000003','scattering','Scattering of light','Why the sky is blue and sunsets are red.',4,$c${"explanation":"Small particles and gas molecules scatter light, and the scattering of light by particles much smaller than its wavelength is stronger for shorter wavelengths, approximately proportional to 1/λ⁴. Blue light is therefore scattered far more than red light, so scattered blue light reaches our eyes from all directions and the sky looks blue. Near the horizon at sunset, light travels a longer path through the atmosphere; much of the blue is scattered away and the direct light appears red or orange. Red is used for danger signals because it is scattered least and remains visible over long distances.","examples":[{"problem":"Why does the sky appear blue during the day?","solution":"Air molecules scatter short-wavelength blue light much more strongly than red light, so blue reaches the eye from all parts of the sky."},{"problem":"Why is the Sun redder at sunset?","solution":"Sunlight crosses more atmosphere, so more blue light is scattered out of the direct beam and the remaining light looks red."}],"misconceptions":["The sky reflects the blue of the oceans.","Sunlight itself changes colour during the day.","Red light is scattered more strongly than blue."],"revision_notes":"Rayleigh scattering ∝ 1/λ⁴. Blue sky: short wavelengths scattered. Red sunset: long path removes blue. Red signals: least scattered."}$c$::jsonb),
('20000000-0000-4000-8000-000000000301','10000000-0000-4000-8000-000000000004','magnetic-field','Magnetic field and field lines','Describing magnetic fields with lines and compasses.',0,$c${"explanation":"A magnetic field is the region around a magnet or current in which magnetic force can act. Field lines show its direction, from the north pole to the south pole outside a magnet and continuing inside it, forming closed loops. Where lines are closer together the field is stronger. Field lines never cross, because a compass at a point can point in only one direction. A uniform field, such as between the poles of a strong horseshoe magnet, has parallel, equally spaced lines. A compass needle aligns with the local field.","examples":[{"problem":"Why can two magnetic field lines never intersect?","solution":"At an intersection the field would have two directions at one point, but a compass needle can point only one way."},{"problem":"How does the spacing of field lines indicate field strength?","solution":"Closer lines mean a stronger magnetic field; widely spaced lines mean a weaker field."}],"misconceptions":["Field lines start at the north pole and simply end in space.","Field lines can cross at neutral points.","A stronger field is shown by more widely spaced lines."],"revision_notes":"Field lines: north to south outside a magnet, closed loops, never cross. Dense lines = strong field."}$c$::jsonb),
('20000000-0000-4000-8000-000000000302','10000000-0000-4000-8000-000000000004','field-due-to-current','Magnetic field due to current','Concentric fields around a wire and uniform fields in a solenoid.',1,$c${"explanation":"A current-carrying conductor produces a magnetic field around it. Around a long straight wire the field lines are concentric circles in planes perpendicular to the wire; reversing the current reverses their direction. The right-hand thumb rule gives the direction: point the right thumb along the current and the curled fingers show the field. Bending the wire into a loop concentrates the field inside the loop. In a solenoid, the field inside is nearly uniform and parallel to the axis, and the solenoid behaves like a bar magnet. An electromagnet uses a current in a coil, often with an iron core, and can be switched on and off.","examples":[{"problem":"How does the field of a straight wire change if the current is reversed?","solution":"The field lines remain concentric circles, but their direction reverses."},{"problem":"Where is the magnetic field of a solenoid strongest and most uniform?","solution":"Inside the solenoid, along its axis."}],"misconceptions":["A current-carrying wire has no field unless it is coiled.","The field around a straight wire points along the wire.","An electromagnet stays magnetic after the current is switched off."],"revision_notes":"Straight wire: concentric circles, right-hand thumb rule. Solenoid: uniform field inside, behaves like a bar magnet."}$c$::jsonb),
('20000000-0000-4000-8000-000000000303','10000000-0000-4000-8000-000000000004','force-on-conductor','Force on a current-carrying conductor','Magnetic force on a wire in a field and Fleming’s left-hand rule.',2,$c${"explanation":"A current-carrying conductor placed in a magnetic field experiences a force when the current has a component perpendicular to the field. The force is greatest when the conductor is perpendicular to the field and zero when it is parallel to it. Its magnitude is F = BIL sin θ, where B is the magnetic flux density, I the current, L the length in the field and θ the angle between the conductor and the field. Fleming’s left-hand rule predicts the direction: the first finger points along the field, the second along the current and the thumb gives the force.","examples":[{"problem":"A 0.20 m wire carries 3.0 A perpendicular to a 0.50 T field. Find the force.","solution":"F = BIL = 0.50 × 3.0 × 0.20 = 0.30 N, perpendicular to both the field and the wire."},{"problem":"When is the force on a current-carrying wire in a magnetic field zero?","solution":"When the wire is parallel to the field, because sin 0° = 0."}],"misconceptions":["The force is largest when the wire is parallel to the field.","The force acts along the wire.","Doubling the current quadruples the force."],"revision_notes":"F = BIL sin θ. Maximum when perpendicular (θ = 90°), zero when parallel. Fleming’s left-hand rule gives direction."}$c$::jsonb),
('20000000-0000-4000-8000-000000000304','10000000-0000-4000-8000-000000000004','electric-motor','The electric motor','Converting electrical energy into rotation with a commutator.',3,$c${"explanation":"An electric motor uses the force on a current-carrying coil in a magnetic field to produce rotation. When current flows in the coil, opposite sides carry current in opposite directions and experience forces that turn the coil. A split-ring commutator reverses the current in the coil every half turn, so the forces continue to drive rotation in the same direction instead of stopping when the coil becomes vertical. The motor converts electrical energy into mechanical energy. Increasing current, field strength or the number of turns increases the turning effect.","examples":[{"problem":"What is the purpose of the split-ring commutator?","solution":"It reverses the current in the coil each half rotation so the magnetic forces keep turning the coil in one direction."},{"problem":"At which coil position is the turning effect zero?","solution":"When the coil plane is perpendicular to the field, the forces act along the same line and produce no turning effect."}],"misconceptions":["The commutator increases the current.","The motor works without a magnetic field.","The coil stops permanently when it first becomes vertical."],"revision_notes":"Motor: electrical to mechanical energy. Commutator reverses current every half turn. Force on coil sides produces rotation."}$c$::jsonb),
('20000000-0000-4000-8000-000000000305','10000000-0000-4000-8000-000000000004','electromagnetic-induction','Electromagnetic induction','Generating current by changing magnetic flux.',4,$c${"explanation":"Electromagnetic induction occurs when a conductor experiences a changing magnetic field: an electromotive force is induced and, in a closed circuit, a current flows. Moving a magnet into or out of a coil, or moving the coil in a field, deflects a galvanometer and shows an induced current. The induced current is larger when the magnet moves faster, when the coil has more turns, or when a stronger magnet is used. Reversing the motion reverses the current. An electric generator uses this effect, converting mechanical energy into electrical energy, and the induced current alternates as the coil rotates.","examples":[{"problem":"A magnet is pushed quickly into a coil, then slowly. When is the induced current larger?","solution":"When the magnet moves quickly, because the magnetic flux changes at a greater rate."},{"problem":"What energy conversion occurs in a generator?","solution":"Mechanical energy is converted into electrical energy by electromagnetic induction."}],"misconceptions":["A stationary magnet inside a coil induces a steady current.","Induced current does not depend on the speed of motion.","Generators create charge from nothing rather than converting energy."],"revision_notes":"Changing flux induces emf. Faster motion, more turns or a stronger magnet increase the induced current. Generator: mechanical → electrical."}$c$::jsonb)
